-- GENERATED by `wfj generate` from data/spell/spell-0416.jsonl. Do not edit: `wfj validate` regenerates and diffs it.
local _, WFJ = ...
WFJ.Data.add("spell", {
  [416002] = { "Incidi sui tuoi stivali la runa Gladiator Stance:\n\n$I1\nUna postura aggressiva che, mentre indossi uno scudo, aumenta i danni del $N1% e la probabilità di blocco del $N2%, ma riduce l'Armatura del $N3% e la minaccia generata del $N4%. Inoltre, ottieni il $N5% di rabbia in più quando il tuo attacco automatico danneggia un nemico che non ti ha come bersaglio.\n\nMentre indossi uno scudo in Gladiator Stance, puoi usare tutte le abilità riservate alle altre posture.", nil, 0xa64ff401, nil, "um" },
  [416003] = { "Incidi sui tuoi guanti la runa Single-Minded Fury:\n\n$I1\nMentre combatti con due armi, la tua velocità di movimento aumenta del $N1% e ottieni il $N2% di velocità d'attacco ogni volta che il tuo attacco automatico in mischia colpisce lo stesso bersaglio dell'attacco automatico precedente, effetto che si accumula fino a $N3 volte. Dura $D1 o finché il tuo attacco automatico non colpisce un bersaglio diverso.", nil, 0x63801b3d, nil, "um" },
  [416004] = { "Incidi sulla tua cintura la runa Impeto di Sangue:\n\n$I1\nAssalto Eroico, Sete di Sangue e Turbine hanno una probabilità del $N1% di rendere istantanea la tua prossima Contusione entro $D1, di farla colpire con entrambe le armi da mischia e di renderla senza costo in rabbia.", nil, 0xf732cd1e, nil, "um" },
  [416005] = { "Incidi sulla tua cintura la runa Precision Timing:\n\n$I1\nContusione ora è istantanea, ma ha un tempo di recupero di $D1.", nil, 0xef96d5a9, nil, "um" },
  [416008] = { "Incidi sui tuoi gambali la runa Everlasting Affliction:\n\n$I1\nOgni volta che il tuo incantesimo Risucchio di Vita, Risucchio d'Anima o Dardo d'Ombra infligge danni, la tua Corruzione sul bersaglio viene riportata alla durata massima.", nil, 0x83f42112, nil, "um" },
  [416009] = { "Incidi sulla tua armatura per il torso o sulla tua veste la runa Tattiche Demoniache:\n\n$I1\nAumenta del $N1% la probabilità di colpo critico di tutti gli attacchi tuoi e del tuo demone evocato mentre il demone è attivo.", nil, 0x19bb25eb, nil, "um" },
  [416014] = { "Incidi sui tuoi stivali la runa Conoscenza Demoniaca:\n\n$I1\nAumenta i danni magici tuoi e del tuo famiglio demoniaco fino al $N1% del tuo livello mentre hai un famiglio demoniaco evocato attivo.", nil, 0x4f2489e2, nil, "um" },
  [416015] = { "Incidi sui tuoi bracciali la runa Incenerimento:\n\n$I1\nInfligge $N1 danni da fuoco al bersaglio e un ulteriore $N2% di danni se il bersaglio è afflitto da Immolazione.", nil, 0x296e95c6, nil, "um" },
  [416017] = { "Incidi sui tuoi stivali la runa Dance of the Wicked:\n\n$I1\nOgni volta che infliggi un colpo critico a un nemico, tu e il tuo famiglio demoniaco ottenete una probabilità di schivata pari al $N1% della tua probabilità di critico magico, e recuperate entrambi il $N2% del mana massimo.", nil, 0xae65ca31, nil, "um" },
  [416028] = { "Incidi sui tuoi stivali la runa Scudo Sacro:\n\n$I1\nOgni volta che il bersaglio subisce danni ottiene uno Scudo Sacro, che assorbe $N1 danni e aumenta del $N2% la probabilità del Paladino di infliggere un colpo critico con Lampo di Luce per un massimo di $D1. Inoltre, fa sì che il tuo Lampo di Luce curi i bersagli con Scudo Sacro di un ulteriore $N4% in $D2. Non possono ottenere questo effetto più di una volta ogni $D3. Dura $D4. Questo incantesimo non può essere attivo su più di un bersaglio alla volta.", nil, 0x84afb489, nil, "um" },
  [416031] = { "Incidi sui tuoi stivali la runa The Art of War:\n\n$I1\nAumenta del $N1% tutti i danni da sacro che infliggi, e i tuoi colpi critici in mischia e magici riducono di $D1 il tempo di recupero rimanente del tuo incantesimo Esorcismo.", nil, 0x36ce3657, nil, "um" },
  [416035] = { "Incidi sui tuoi stivali la runa Protezione della Luce:\n\n$I1\nDopo aver bloccato un attacco in mischia, ottieni il $N1% del tuo mana massimo ogni $D1 per $D2. Questo effetto viene annullato se lanci Lampo di Luce, Luce Sacra o Folgore Sacra.", nil, 0x2f71e716, nil, "um" },
  [416042] = { "Incidi sulla tua armatura per il torso o sulla tua veste la runa Legge del Più Forte:\n\n$I1\nRiduce del $N1% la probabilità di subire colpi critici dagli attacchi in mischia e riduce del $N2% tutti i danni subiti. Danni subiti ridotti di un ulteriore $N3% mentre sei in Forma d'Orso o Dire Bear Form.", nil, 0x4d8ef5c6, nil, "um" },
  [416044] = { "Incidi sui tuoi guanti la runa Fuoco Solare:\n\n$I1\nBrucia il nemico infliggendo $N1 danni da natura e poi altri $N2 danni da natura in $D1.\n\nInoltre, mentre sei in ⟦Bear Form=Forma d'Orso⟧, ⟦Cat Form=Forma Felina⟧ o ⟦Dire Bear Form=Forma d'Orso Crudele⟧, il tuo Fuoco Lunare è sostituito da Fuoco Solare (Orso) o Fuoco Solare (Felino). Questo incantesimo beneficia di tutti gli effetti associati a Fuoco Lunare e li attiva.\n\nFuoco Solare (Orso)\nBrucia il nemico infliggendo $N4 danni da natura e poi altri $N5 danni da natura in $D2.\n\nFuoco Solare (Felino)\nBrucia il nemico infliggendo $N7 danni da natura e poi altri $N8 danni da natura in $D3. Fornisce $N10 punti combo.", nil, 0xbed3fd8c, nil, "um" },
  [416046] = { "Incidi sui tuoi guanti la runa Craniata:\n\n$I1\nCarica un bersaglio entro $N1 m e lo colpisce al cranio, interrompendone il lancio d'incantesimi e impedendo di lanciare incantesimi di quella scuola per $D1. Condivide il tempo di recupero con Carica Ferina.", nil, 0xd5ab304e, nil, "um" },
  [416049] = { "Incidi sui tuoi gambali la runa Lacerazione:\n\n$I1\nLacera il bersaglio nemico, facendolo sanguinare e infliggendo $N1 danni in $D1, più il $N3% dei danni dell'arma per ogni applicazione di Lacerazione già presente sul bersaglio. Genera un'elevata quantità di minaccia. L'effetto si cumula fino a $N4 volte sullo stesso bersaglio.", nil, 0x38fe500a, nil, "um" },
  [416050] = { "Incidi sulla tua armatura per il torso o sulla tua veste la runa Living Seed:\n\n$I1\nQuando curi in modo critico il bersaglio con un incantesimo di cura non periodico, pianti su di esso un Living Seed pari al $N1% della quantità curata. Il Living Seed sboccia la volta successiva che il bersaglio subisce danni o riceve una cura non periodica. Dura $D1.", nil, 0x13ee1dbb, nil, "um" },
  [416051] = { "Incidi sui tuoi bracciali la runa Elune's Fires:\n\n$I1\nAlcuni dei tuoi incantesimi e delle tue abilità prolungano la durata dei tuoi effetti di danno e di cura periodici sul bersaglio:\n\nFuoco Stellare prolunga Fuoco Lunare di $D1.\nIra Silvana prolunga Fuoco Solare di $D2.\nRicrescita prolunga Rinvigorimento di $D3.\nArtigliata prolunga Squarcio di $D4.\n\nOgni effetto può essere prolungato al massimo fino alla sua durata iniziale.", nil, 0x8484bc0a, nil, "um" },
  [416054] = { "Incidi sulla tua cintura la runa ⟦Power Surge=Picco Energetico⟧:\n\n$I1\nOgni volta che Folgore del Fuoco infligge danni, ha il $N1% di probabilità di azzerare il tempo di recupero di Getto di Lava e Catena di Fulmini e di rendere istantaneo il tuo prossimo Getto di Lava o Catena di Fulmini entro $D1. Ogni volta che Marea Gelida cura, ha il $N3% di probabilità di rendere istantanea la tua prossima Catena di Guarigione entro $D2. Inoltre, ogni $D3 ottieni mana pari al $N6% del tuo Intelletto.", nil, 0xce292ee1, nil, "um" },
  [416055] = { "Incidi sul tuo elmo la runa Mental Dexterity:\n\n$I1\nAumenta la tua potenza d'attacco di un valore pari al $N1% del tuo Intelletto.", nil, 0xe5cd1b79, nil, "um" },
  [416057] = { "Incidi sulla tua armatura per il torso o sulla tua veste la runa Pioggia Curativa:\n\n$I1\nSeleziona l'area di $N1 m intorno al giocatore bersaglio e cura tutti i membri del suo gruppo presenti in quell'area di $N2 ogni secondo.", nil, 0x0154268c, nil, "um" },
  [416062] = { "Incidi sul tuo mantello la runa Coherence:\n\n$I1\nL'efficacia di Catena di Guarigione si riduce solo del $N1% a ogni balzo e quella di Catena di Fulmini solo del $N2% a ogni balzo. Entrambe balzano inoltre su $N3 bersaglio aggiuntivo.", nil, 0xb0021a71, nil, "um" },
  [416066] = { "Incidi sul tuo elmo la runa Vampata:\n\n$I1\nFolgore del Fuoco ora colpisce fino a $N1 bersagli, la sua durata aumenta di $D1 e infligge il $N3% di danni in più. Inoltre, mentre l'arma equipaggiata nella mano primaria è infusa con Arma della Lingua di Fuoco, i tuoi danni magici aumentano di un valore pari al $N4% del tuo Intelletto.", nil, 0xac8ad962, nil, "um" },
  [416081] = { "Ottieni l'abilità Coherence:\n\n$I1\nL'efficacia di Catena di Guarigione si riduce solo del $N1% a ogni balzo e quella di Catena di Fulmini solo del $N2% a ogni balzo. Entrambe balzano inoltre su $N3 bersaglio aggiuntivo.", nil, 0x09dca7ef, nil, "um" },
  [416083] = { "Incidi sul tuo elmo la runa Riflessi Felini:\n\n$I1\nAumenta la tua probabilità di schivata del $N1% e quella del tuo famiglio del $N2%. Inoltre, riduce del $N3% il tempo di recupero della tua abilità Assalto Fiancheggiato.", nil, 0x62167ba0, nil, "um" },
  [416084] = { "Incidi sulla tua cintura la runa Aspetto della Vipera:\n\n$I1\nIl Cacciatore assume l'aspetto della vipera: i tuoi attacchi automatici a distanza e in mischia rigenerano mana, ma i danni totali che infliggi sono ridotti del $N1%. Inoltre, ottieni il $N2% del mana massimo ogni $D1. Il mana ottenuto dipende dalla velocità dell'arma. Può essere attivo un solo Aspetto alla volta.", nil, 0xbc7e4fbf, nil, "um" },
  [416085] = { "Incidi sul tuo elmo la runa Pronto al Tiro:\n\n$I1\nOgni volta che piazzi una trappola, la tua prossima abilità di tiro (tranne Tiro Disorientante) entro $D1 non costa mana e non attiva il tempo di recupero.", nil, 0x8bef56d4, nil, "um" },
  [416086] = { "Incidi sulla tua cintura la runa Melee Specialist:\n\n$I1\nAssalto del Raptor è ora istantaneo, e Morso della Mangusta e Assalto del Raptor hanno il $N1% di probabilità a ogni attacco di azzerare i tempi di recupero di Morso della Mangusta e Assalto del Raptor.", nil, 0xd798d541, nil, "um" },
  [416087] = { "Incidi sulla tua cintura la runa Tiro Mortale:\n\n$I1\nTenti di finire un bersaglio ferito con un attacco a distanza che infligge il $N1% dei danni dell'arma più $N2. Tiro Mortale non ha gittata minima. Il tempo di recupero di Tiro Mortale si azzera se lo usi su un nemico con il $N3% di salute o meno.", nil, 0xdce2128a, nil, "um" },
  [416089] = { "Incidi sui tuoi stivali la runa Wyvern Strike:\n\n$I1\nSostituisce la tua abilità Morso della Viverna con Wyvern Strike, un assalto feroce che infligge il $N1% dei danni dell'arma e fa sanguinare il bersaglio, infliggendo danni nel tempo.\n\nWyvern Strike richiede il talento Morso della Viverna e sostituisce le abilità Morso della Viverna del libro degli incantesimi Sopravvivenza.", nil, 0x0a678dd2, nil, "um" },
  [416090] = { "Incidi sul tuo elmo la runa Uccisione Rapida:\n\n$I1\nRiduce il tempo di recupero della tua abilità Rapidità di Tiro di $D1. Inoltre, quando uccidi un nemico non banale o questi muore mentre è afflitto dal tuo Morso del Serpente, ottieni Uccisione Rapida, che aumenta del $N3% i danni della tua prossima abilità di tiro entro $D2.", nil, 0xbecee8c6, nil, "um" },
  [416091] = { "Incidi sui tuoi gambali la runa Sniper Training:\n\n$I1\nQuando non ti sei mosso nell'ultimo $D1, hai il $N2% di probabilità di ottenere Sniper's Aim, cumulabile fino a $N3 volte. Sniper's Aim aumenta del $N4% la probabilità di critico delle tue abilità di tiro.", nil, 0x5849af1c, nil, "um" },
  [416093] = { "Incidi sui tuoi bracciali la runa Raptor Fury:\n\n$I1\nAssalto del Raptor aumenta del $N1% i danni inflitti da Assalto del Raptor e Morso della Mangusta per $D1, effetto cumulabile fino a $N3 volte. Le applicazioni successive non prolungano la durata di questo effetto.", nil, 0x34e5d6c2, nil, "um" },
  [416288] = { "Combina con altri $N1 pezzi per ottenere la mappa completa.", nil, 0xdcc7f5cf, nil, "um" },
  [416304] = { "Dissotterra il tesoro nel punto segnato", nil, 0xcb9fbb49, nil, "um" },
  [416772] = { "Da piazzare come esca vicino alla tana di un felino dell'isola", nil, 0xaf609f27, nil, "um" },
  [416837] = { nil, "Hai trovato un amico!", nil, 0x135ae248, "mu" },
  [416861] = { "La tua abilità ⟦Tame Beast=Addomesticamento⟧ funziona anche sulle vipere (come mascotte)", "La tua abilità ⟦Tame Beast=Addomesticamento⟧ funziona anche sulle vipere (come mascotte)", 0xe11da250, 0xe11da250, "uu" },
})
